describe('beforeSession failure', () => {
  // specs/hal-engine-config-hooks/spec.md#8
  it('passes the original session and error to cleanup hooks before rejecting without calling the provider', async () => {
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
    };
    const failure = new Error('setup failed');
    const calls: unknown[][] = [];
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        calls.push(['provider']);
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        beforeSession: async received => {
          calls.push(['beforeSession', received]);
          throw failure;
        },
        onError: async (received, error) => {
          calls.push(['onError', received, error]);
        },
        afterSession: async received => {
          calls.push(['afterSession', received]);
        },
      },
    });

    const rejection = await orchestrator.processMessage(session).then(
      () => undefined,
      (error: Error) => error
    );

    expect({rejection, calls}).toEqual({
      rejection: failure,
      calls: [
        ['beforeSession', session],
        ['onError', session, failure],
        ['afterSession', session],
      ],
    });
  });
});

